import math

def interp(points,x):
    p=sorted(points)
    for a,b in zip(p,p[1:]):
        if a[0]<=x<=b[0] and b[0]-a[0]>0.001:
            q=(x-a[0])/(b[0]-a[0])
            return a[1]+q*(b[1]-a[1])
    return None

def control(obs):
    rails=obs.get('local_map',{})
    left=rails.get('left_rail',[])
    right=rails.get('right_rail',[])
    phi=obs.get('hitch_deg',0)
    centers=[]
    for x in [2,3,4,5,6]:
        a=interp(left,x); b=interp(right,x)
        if a is not None and b is not None:
            centers.append((x,(a+b)/2))
    if not centers:
        wake('Cannot see both rails ahead')
        return (phi,0,180)
    x,y=min(centers,key=lambda p:abs(p[0]-5))
    curvature=2*y/(x*x+y*y)
    desired=math.degrees(math.atan(3.6*curvature))
    desired=max(-29,min(29,desired))
    equilibrium=math.degrees(math.atan(2.5*math.sin(math.radians(phi))/(3.6+1.3*math.cos(math.radians(phi)))))
    steer=equilibrium+1.8*(phi-desired)
    steer=max(-45,min(45,steer))
    speed=-0.75 if abs(phi)<27 else -0.45
    if abs(phi)>45:
        wake('Hitch angle needs recovery')
        speed=0
    return (steer,speed,180)

