import math

def interp(points,x):
    p=sorted(points)
    if len(p)<2: return None
    for a,b in zip(p,p[1:]):
        if a[0]<=x<=b[0] and b[0]-a[0]>0.001:
            return a[1]+(x-a[0])*(b[1]-a[1])/(b[0]-a[0])
    if x>p[-1][0]:
        a,b=p[-2:]
        if b[0]-a[0]>0.001:
            return b[1]+(x-b[0])*(b[1]-a[1])/(b[0]-a[0])
    return None

def control(obs):
    rails=obs.get('local_map',{})
    a=interp(rails.get('left_rail',[]),5)
    b=interp(rails.get('right_rail',[]),5)
    phi=obs.get('hitch_deg',0)
    if a is None or b is None:
        wake('Bay rails lost')
        return (phi,0,180)
    y=(a+b)/2
    desired=math.degrees(math.atan(3.6*2*y/(25+y*y)))
    desired=max(-29,min(29,desired))
    equilibrium=math.degrees(math.atan(2.5*math.sin(math.radians(phi))/(3.6+1.3*math.cos(math.radians(phi)))))
    steer=max(-45,min(45,equilibrium+1.8*(phi-desired)))
    return (steer,-0.5,180)

