import math

def interp(points,x):
    pts=sorted(points)
    for a,b in zip(pts,pts[1:]):
        if a[0]<=x<=b[0] and b[0]-a[0]>0.001:
            t=(x-a[0])/(b[0]-a[0]); return a[1]+t*(b[1]-a[1])
    return None

def control(obs):
    rails=obs.get('local_map',{})
    left=rails.get('left_rail',[]); right=rails.get('right_rail',[])
    if not left or not right: return (0,0,180)
    look=min(12.0,max(p[0] for p in left)-0.2,max(p[0] for p in right)-0.2)
    yl=interp(left,look); yr=interp(right,look)
    if yl is None or yr is None: return (0,0,180)
    y=(yl+yr)/2
    k=2*y/((look+1.9)**2+y*y)
    desired=max(-35,min(35,math.degrees(math.atan(10.2*k))))
    beta=obs['hitch_deg']
    ff=math.degrees(math.atan(3.9*math.sin(math.radians(beta))/10.2))
    steer=max(-42,min(42,ff+1.5*(beta-desired)))
    return (steer,-0.95,180)

